What does `Label` render?

```jsx
const Ctx = createContext({ n: -1 });

function Label() {
  const { n } = useContext(Ctx);
  return <span>{n}</span>;
}

export default function App() {
  return (
    <Ctx value={{ n: 1 }}>
      <Ctx value={{ n: 2 }}>
        <Label />
      </Ctx>
    </Ctx>
  );
}
```

