After the first render, the user clicks "tick". Which logs appear?

```jsx
const Ctx = createContext(null);

const MemoConsumer = memo(function MemoConsumer() {
  const { n } = useContext(Ctx);
  console.log('consumer', n);
  return null;
});
const MemoPlain = memo(function MemoPlain() {
  console.log('memoPlain');
  return null;
});
function Plain() {
  console.log('plain');
  return null;
}

function App() {
  const [tick, setTick] = useState(0);
  const [n] = useState(0);
  return (
    <Ctx value={{ n }}>
      <button onClick={() => setTick(tick + 1)}>tick</button>
      <MemoConsumer />
      <MemoPlain />
      <Plain />
    </Ctx>
  );
}
```

