The provider below takes its subtree as `children`. After `setCount(1)` is called, which components re-render?

```jsx
const CountCtx = createContext(null);

function CountProvider({ children }) {
  const [count, setCount] = useState(0);
  return <CountCtx value={{ count, setCount }}>{children}</CountCtx>;
}

function Static() { return <p>hello</p>; }
function Reader() { const { count } = useContext(CountCtx); return <p>{count}</p>; }
function IncrementButton() {
  const { setCount } = useContext(CountCtx);
  return <button onClick={() => setCount((c) => c + 1)}>+</button>;
}

<CountProvider>
  <Static />
  <Reader />
  <IncrementButton />
</CountProvider>
```

State and its setter are provided through two separate contexts. After `setX(5)`, which memoized components re-render?

```jsx
const XState = createContext(0);
const XDispatch = createContext(null);

function XProvider({ children }) {
  const [x, setX] = useState(0);
  return (
    <XDispatch value={setX}>
      <XState value={x}>{children}</XState>
    </XDispatch>
  );
}

const OnlyDispatch = memo(function OnlyDispatch() {
  const setX = useContext(XDispatch);
  return <button onClick={() => setX(5)}>set</button>;
});
const OnlyState = memo(function OnlyState() {
  const x = useContext(XState);
  return <p>{x}</p>;
});
```

Which of these components re-render when `useStore.getState().incC()` changes only `c`?

```jsx
const useStore = create((set) => ({
  a: 1, b: 2, c: 0,
  incC: () => set((s) => ({ c: s.c + 1 })),
}));

function A() { const a = useStore((s) => s.a); return a; }
function Whole() { const s = useStore(); return s.a; }
function Sum() { const sum = useStore((s) => s.a + s.b); return sum; }
```

With Zustand 5, this component crashes with "Maximum update depth exceeded" and a warning that "The result of getSnapshot should be cached". Why, and what is the idiomatic fix?

```jsx
function Profile() {
  const { name, email } = useUserStore((s) => ({ name: s.name, email: s.email }));
  return <p>{name} ({email})</p>;
}
```

A component subscribes to a custom store as shown. While it renders three times, how many subscribe and unsubscribe calls does the store see?

```jsx
function Online() {
  const online = useSyncExternalStore(
    (cb) => store.subscribe(cb),
    () => store.getSnapshot(),
  );
  return <p>{String(online)}</p>;
}
```
